class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        k = 1
        while True:
            hours = 0
            for pile in piles:
                hours += (pile + k - 1) // k
            if hours <= h:
                return k
            k += 1

class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        slowest, fastest = 1, max(piles)
        while slowest < fastest:
            k = (slowest + fastest) // 2
            hours = 0
            for pile in piles:
                hours += (pile + k - 1) // k
            if hours <= h:
                fastest = k
            else:
                slowest = k + 1
        return slowest
